import os
import json
import pandas as pd
import math
import logging


def eval():
    pred_dir = "pred_results"

    required_files = ["ffield.csv", "evolution.log", "pred_train.json"]

    # Step 1: Check file existence
    for fname in required_files:
        pred_path = os.path.join(pred_dir, fname)
        if not os.path.exists(pred_path):
            return (False, f"Missing predicted output file: {pred_path}")

    # Step 2: Validate and load pred_train.json
    try:
        with open(os.path.join(pred_dir, "pred_train.json"), "r") as <local-path>            pred_json = json.load(f)
    except (json.JSONDecodeError, Exception) as <local-path>        return (False, f"pred_results/pred_train.json is not valid JSON: {e}")

    # Check required keys in pred JSON - accept alternate key names
    alt_key_map = {
        "iterations": ["iterations", "iteration_count"],
        "final_score": ["final_score"],
        "convergence": ["convergence_achieved", "convergence_status", "converged"],
    }

    def get_key(d, key_options):
        for k in key_options:
            if k in <local-path>                return d[k]
        return None

    pred_iterations = get_key(pred_json, alt_key_map["iterations"])
    pred_final_score = get_key(pred_json, alt_key_map["final_score"])
    pred_convergence = get_key(pred_json, alt_key_map["convergence"])

    if pred_iterations is None:
        return (False, "pred_train.json missing iteration count (iterations/iteration_count)")
    if pred_final_score is None:
        return (False, "pred_train.json missing final_score")
    if pred_convergence is None:
        return (False, "pred_train.json missing convergence status (convergence_achieved/convergence_status/converged)")

    # Check for NaN/Inf in final score
    if not isinstance(pred_final_score, (int, float)) or math.isnan(pred_final_score) or math.isinf(pred_final_score):
        return (False, f"final_score is not a valid number: {pred_final_score}")

    # Check iterations is a valid positive number
    if not isinstance(pred_iterations, (int, float)) or pred_iterations < 1:
        return (False, f"Iteration count is invalid: {pred_iterations}")

    # Check convergence status is present and meaningful
    if pred_convergence is None:
        return (False, "Convergence status is missing")

    # Step 3: Validate ffield.csv
    try:
        pred_csv = pd.read_csv(os.path.join(pred_dir, "ffield.csv"))
    except Exception as <local-path>        return (False, f"Failed to parse pred_results/ffield.csv: {e}")

    if "score" not in pred_csv.columns:
        return (False, "ffield.csv missing 'score' column")

    if len(pred_csv) < 2:
        return (False, f"ffield.csv has too few rows ({len(pred_csv)}), expected optimization history with multiple entries")

    # Check for NaN/Inf in CSV
    if pred_csv.isnull().any().any():
        return (False, "ffield.csv contains NaN values")

    param_cols = [c for c in pred_csv.columns if c != "score"]
    if len(param_cols) == 0:
        return (False, "ffield.csv has no parameter columns")

    for col in param_cols:
        vals = pred_csv[col]
        for v in vals:
            if isinstance(v, float) and math.isinf(v):
                return (False, f"ffield.csv column '{col}' contains Inf values")

    # Step 4: Validate evolution.log is non-empty
    pred_log_path = os.path.join(pred_dir, "evolution.log")
    if os.path.getsize(pred_log_path) == 0:
        return (False, "evolution.log is empty")

    # Step 5: Check log file has meaningful content (multiple lines indicating progress)
    with open(pred_log_path, "r") as <local-path>        log_lines = f.readlines()
    if len(log_lines) < 2:
        return (False, f"evolution.log has too few entries ({len(log_lines)}), expected detailed optimization progress")

    # Step 6: Check optimization produced meaningful results
    # The CSV should show the optimization history - check that scores vary
    scores = pred_csv["score"].values
    if len(set(scores)) < 2:
        return (False, "All scores in ffield.csv are identical - no optimization occurred")

    # Step 7: Verify parameter columns have reasonable values (not all identical)
    for col in param_cols:
        col_vals = pred_csv[col].values
        if len(set(col_vals)) < 2:
            # At least some parameter columns should vary
            pass  # Not all need to vary, just check overall

    # Check that at least one parameter column varies
    any_variation = any(len(set(pred_csv[col].values)) > 1 for col in param_cols)
    if not any_variation:
        return (False, "No parameter variation detected in ffield.csv - optimization did not explore parameter space")

    # Step 8: Check that the JSON final_score is consistent with CSV scores
    # The final score should be close to the best score in the CSV
    best_csv_score = pred_csv["score"].min()
    worst_csv_score = pred_csv["score"].max()

    # Final score should be within the range of observed scores (with some tolerance)
    score_range = abs(worst_csv_score - best_csv_score)
    tolerance = max(score_range * 2.0, abs(best_csv_score) * 0.5, 1.0)  # generous tolerance

    if abs(pred_final_score - best_csv_score) > tolerance and abs(pred_final_score - worst_csv_score) > tolerance:
        # Just warn, don't fail - the final score might be from a different evaluation
        pass

    # Step 9: Verify the optimization ran for a reasonable number of iterations
    # Should have at least 2 iterations (initial + at least one generation)
    if pred_iterations < 2:
        return (False, f"Too few iterations ({pred_iterations}), optimization should run for multiple generations")

    # Step 10: Check that param columns match what's expected
    # Should have at least 1 parameter column
    if len(param_cols) < 1:
        return (False, "ffield.csv should have at least 1 parameter column besides 'score'")

    # All checks passed
    ml_r2 = pred_json.get("ml_model_r2", "N/A")
    return (True, f"Evaluation passed: {len(pred_csv)} parameter sets in history, "
                  f"final_score={pred_final_score:.4f}, iterations={pred_iterations}, "
                  f"convergence={pred_convergence}, "
                  f"param_cols={len(param_cols)}, "
                  f"ML R²={ml_r2}")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import numpy as np
import os

PRED_FILE = 'pred_results/pred_feature.npy'

# Possible key name mappings (solution key -> acceptable alternatives)
ONE_HOT_KEYS = {'aatype', 'one_hot', 'onehot', 'sequence_encoding'}
PROFILE_KEYS = {'hhblits_profile', 'msa_profile', 'profile', 'reweighted_profile', 'non_gapped_profile'}
GAP_KEYS = {'gap_stats', 'gap_matrix', 'deletion_probability', 'gap_frequency'}
MI_KEYS = {'mutual_info', 'mutual_information', 'mi_matrix'}
PSEUDO_KEYS = {'pseudolikelihood', 'pseudo_frob', 'pseudo_bias'}
HMM_KEYS = {'hhblits_profile', 'hmm_profile', 'hhm_profile'}


def find_key(data_dict, key_set):
    """Find first matching key from a set of possible key names."""
    for key in key_set:
        if key in data_dict:
            return key
    return None


def load_pred_data(filepath):
    """Load predicted data, handling both dict and array-of-dicts formats."""
    raw = np.load(filepath, allow_pickle=True)

    # Handle scalar array containing a dict
    if isinstance(raw, np.ndarray) and raw.ndim == 0:
        item = raw.item()
        if isinstance(item, dict):
            return item
        return item

    # Handle array of dicts
    if isinstance(raw, np.ndarray) and raw.ndim >= 1:
        if len(raw) > 0 and isinstance(raw[0], dict):
            return raw[0]  # Take first entry
        # Try treating the array itself as data
        try:
            item = raw.item()
            if isinstance(item, dict):
                return item
        except (ValueError, AttributeError):
            pass

    # If it's already a dict
    if isinstance(raw, dict):
        return raw

    return raw


def eval():
    # Check file exists
    if not os.path.exists(PRED_FILE):
        return (False, f"Predicted output file not found: {PRED_FILE}")

    # Load predicted data
    try:
        pred_data = load_pred_data(PRED_FILE)
    except Exception as <local-path>        return (False, f"Failed to load predicted file: {e}")

    # Validate it's a dict or dict-like
    if not isinstance(pred_data, dict):
        # Try to convert
        try:
            pred_data = dict(pred_data)
        except Exception:
            return (False, f"Predicted output is not a dictionary (got {type(pred_data).__name__}). "
                          f"Expected a dictionary of feature arrays.")

    if len(pred_data) == 0:
        return (False, "Predicted output dictionary is empty")

    print(f"Loaded features with keys: {list(pred_data.keys())}")

    # =========================================================================
    # Check 1: One-hot / sequence encoding feature
    # =========================================================================
    one_hot_key = find_key(pred_data, ONE_HOT_KEYS)
    if one_hot_key is None:
        return (False, f"No one-hot/sequence encoding feature found. "
                      f"Expected one of: {ONE_HOT_KEYS}. Got keys: {list(pred_data.keys())}")

    one_hot = pred_data[one_hot_key]
    if not isinstance(one_hot, np.ndarray):
        return (False, f"One-hot feature '{one_hot_key}' is not a numpy array")

    if one_hot.ndim != 2:
        return (False, f"One-hot feature '{one_hot_key}' should be 2D, got shape {one_hot.shape}")

    L = one_hot.shape[0]
    if L == 0:
        return (False, "Sequence length is 0")

    # Accept 20, 21, or 22 amino acid encodings
    if one_hot.shape[1] not in [20, 21, 22]:
        return (False, f"One-hot feature '{one_hot_key}' has unexpected number of columns: {one_hot.shape[1]}. "
                      f"Expected 20, 21, or 22.")

    # Check binary values or close to it (some implementations use soft assignments)
    unique_vals = np.unique(one_hot)
    # Should be mostly 0s and 1s (allow small floating point errors)
    if not (np.all(one_hot >= -1e-6) and np.all(one_hot <= 1.0 + 1e-6)):
        return (False, f"One-hot feature '{one_hot_key}' contains values outside [0, 1]")

    # Each row should sum to approximately 1 (or 0 for unknown residues)
    row_sums = one_hot.sum(axis=1)
    if not np.all((row_sums >= 0.9) | (row_sums < 0.1)):
        bad_rows = np.where(~((row_sums >= 0.9) | (row_sums < 0.1)))[0]
        return (False, f"One-hot feature '{one_hot_key}' rows don't sum to ~1: rows {bad_rows[:5]}, sums {row_sums[bad_rows[:5]]}")

    print(f"✓ One-hot encoding: shape {one_hot.shape}, L={L}")

    # =========================================================================
    # Check 2: Profile feature (MSA-derived)
    # =========================================================================
    profile_key = find_key(pred_data, PROFILE_KEYS)
    if profile_key is None:
        # Profile is important but might not always be available (no MSA file)
        print("WARNING: No profile feature found (may be acceptable if no MSA available)")
    else:
        profile = pred_data[profile_key]
        if not isinstance(profile, np.ndarray):
            return (False, f"Profile feature '{profile_key}' is not a numpy array")

        if profile.ndim != 2:
            return (False, f"Profile feature '{profile_key}' should be 2D, got shape {profile.shape}")

        if profile.shape[0] != <local-path>            return (False, f"Profile feature '{profile_key}' has wrong length: {profile.shape[0]} vs {L}")

        # Accept 20, 21, or 22 columns
        if profile.shape[1] not in [20, 21, 22]:
            return (False, f"Profile feature '{profile_key}' has unexpected columns: {profile.shape[1]}")

        # Profile values should be probabilities [0, 1]
        if not (np.all(profile >= -1e-6) and np.all(profile <= 1.0 + 1e-6)):
            return (False, f"Profile feature '{profile_key}' contains values outside [0, 1]")

        # Check for NaN/Inf
        if np.any(np.isnan(profile)) or np.any(np.isinf(profile)):
            return (False, f"Profile feature '{profile_key}' contains NaN or Inf values")

        print(f"✓ Profile feature: '{profile_key}' shape {profile.shape}")

    # =========================================================================
    # Check 3: Gap statistics
    # =========================================================================
    gap_key = find_key(pred_data, GAP_KEYS)
    if gap_key is None:
        print("WARNING: No gap statistics feature found (may be acceptable if no MSA available)")
    else:
        gap_feat = pred_data[gap_key]
        if not isinstance(gap_feat, np.ndarray):
            return (False, f"Gap feature '{gap_key}' is not a numpy array")

        # Gap stats can be 1D (L,), 2D (L,1), or 2D matrix (L,L,1)
        if gap_feat.ndim == 1:
            if gap_feat.shape[0] != <local-path>                return (False, f"Gap feature '{gap_key}' has wrong length: {gap_feat.shape[0]} vs {L}")
        elif gap_feat.ndim == 2:
            if gap_feat.shape[0] != <local-path>                return (False, f"Gap feature '{gap_key}' first dim wrong: {gap_feat.shape[0]} vs {L}")
        elif gap_feat.ndim == 3:
            if gap_feat.shape[0] != L or gap_feat.shape[1] != <local-path>                return (False, f"Gap feature '{gap_key}' wrong shape: {gap_feat.shape}")

        # Values should be in [0, 1] (gap frequencies)
        if np.any(np.isnan(gap_feat)) or np.any(np.isinf(gap_feat)):
            return (False, f"Gap feature '{gap_key}' contains NaN or Inf values")

        print(f"✓ Gap statistics: '{gap_key}' shape {gap_feat.shape}")

    # =========================================================================
    # Check 4: Mutual information / coevolution matrix (optional - requires MSA)
    # =========================================================================
    mi_key = find_key(pred_data, MI_KEYS)
    if mi_key is None:
        print("INFO: No mutual information feature found (may be acceptable if no MSA available)")
    else:
        mi_feat = pred_data[mi_key]
        if not isinstance(mi_feat, np.ndarray):
            return (False, f"MI feature '{mi_key}' is not a numpy array")

        # MI matrix should be at least 2D
        if mi_feat.ndim < 2:
            return (False, f"MI feature '{mi_key}' should be at least 2D, got shape {mi_feat.shape}")

        if mi_feat.shape[0] != <local-path>            return (False, f"MI feature '{mi_key}' first dim wrong: {mi_feat.shape[0]} vs {L}")

        # For pairwise MI, second dim should also be L
        if mi_feat.ndim >= 2 and mi_feat.shape[1] != <local-path>            return (False, f"MI feature '{mi_key}' second dim wrong: {mi_feat.shape[1]} vs {L}")

        # MI values should be non-negative
        if np.any(mi_feat < -1e-6):
            return (False, f"MI feature '{mi_key}' contains negative values (MI should be >= 0)")

        if np.any(np.isnan(mi_feat)) or np.any(np.isinf(mi_feat)):
            return (False, f"MI feature '{mi_key}' contains NaN or Inf values")

        print(f"✓ Mutual information: '{mi_key}' shape {mi_feat.shape}")

    # =========================================================================
    # Check 5: Pseudolikelihood features (optional - requires .mat file)
    # =========================================================================
    pseudo_key = find_key(pred_data, PSEUDO_KEYS)
    if pseudo_key is None:
        print("INFO: No pseudolikelihood feature found (acceptable if no .mat file available)")
    else:
        pseudo_feat = pred_data[pseudo_key]
        if not isinstance(pseudo_feat, np.ndarray):
            return (False, f"Pseudolikelihood feature '{pseudo_key}' is not a numpy array")

        if np.any(np.isnan(pseudo_feat)) or np.any(np.isinf(pseudo_feat)):
            return (False, f"Pseudolikelihood feature '{pseudo_key}' contains NaN or Inf values")

        print(f"✓ Pseudolikelihood: '{pseudo_key}' shape {pseudo_feat.shape}")

    # =========================================================================
    # Check 6: Overall feature count - should have computed multiple features
    # =========================================================================
    num_features = len(pred_data)
    if num_features < 2:
        return (False, f"Too few features computed: {num_features}. Expected at least 2 feature types.")

    print(f"✓ Total features computed: {num_features}")

    # =========================================================================
    # Check 7: Verify sequence length consistency across all array features
    # =========================================================================
    inconsistent_keys = []
    for key, val in pred_data.items():
        if isinstance(val, np.ndarray) and val.ndim >= 1:
            if val.shape[0] != L and val.ndim == 2 and val.shape[0] != <local-path>                inconsistent_keys.append((key, val.shape))

    # Only flag if there are clearly inconsistent shapes (not scalars or metadata)
    serious_inconsistencies = []
    for key, val in pred_data.items():
        if isinstance(val, np.ndarray) and val.ndim >= 2:
            if val.shape[0] != <local-path>                serious_inconsistencies.append((key, val.shape, L))

    if serious_inconsistencies:
        return (False, f"Feature length inconsistency: {serious_inconsistencies}")

    print(f"✓ All features have consistent sequence length L={L}")

    # =========================================================================
    # Summary
    # =========================================================================
    found_features = {
        'one_hot/aatype': one_hot_key,
        'profile': profile_key,
        'gap_stats': gap_key,
        'mutual_info': mi_key,
        'pseudolikelihood': pseudo_key,
    }

    print(f"\nFeature mapping found: {found_features}")
    print(f"All validation checks passed for {num_features} features with L={L}")

    return (True, f"Validation passed: found {num_features} features for sequence of length {L}. "
                  f"Features include: {list(pred_data.keys())}")


if __name__ == '__main__':
    result, reason = eval()
    print(f"\nResult: {result}")
    print(f"Reason: {reason}")

import json
import os
import math
import csv


def eval():
    pred_dir = "pred_results"

    required_files = [
        "pred_fluctuation_energy.json",
        "pred_fluctuation_bo.json",
        "pred_fluctuation_morse.json",
        "pred_fluctuation_summary.csv",
    ]

    # Step 1: Check all required files exist and are non-empty
    for fname in required_files:
        pred_path = os.path.join(pred_dir, fname)
        if not os.path.isfile(pred_path):
            return (False, f"Missing predicted file: {fname}")
        if os.path.getsize(pred_path) == 0:
            return (False, f"Predicted file is empty: {fname}")

    # Step 2: Load and validate JSON files
    json_files = [
        "pred_fluctuation_energy.json",
        "pred_fluctuation_bo.json",
        "pred_fluctuation_morse.json",
    ]

    pred_data = {}
    for fname in json_files:
        try:
            with open(os.path.join(pred_dir, fname), "r") as <local-path>                pred_data[fname] = json.load(f)
        except (json.JSONDecodeError, Exception) as <local-path>            return (False, f"Failed to parse predicted {fname}: {e}")

    # Step 3: Validate JSON structure - each file must be a non-empty dict
    for fname in json_files:
        pred = pred_data[fname]
        if not isinstance(pred, dict) or len(pred) == 0:
            return (False, f"{fname}: predicted data is not a non-empty dict")

    # Step 4: Check that bond type data exists in the JSON files
    expected_bond_types = {'C-C', 'H-H', 'O-O'}

    def find_bond_types_in_dict(d, depth=0):
        """Recursively find all bond type keys in a nested dict."""
        found = set()
        if depth > 3:
            return found
        if isinstance(d, dict):
            for k, v in d.items():
                if k in expected_bond_types:
                    found.add(k)
                else:
                    found.update(find_bond_types_in_dict(v, depth + 1))
        return found

    for fname in json_files:
        pred = pred_data[fname]
        found_bonds = find_bond_types_in_dict(pred)
        if len(found_bonds) == 0:
            return (False, f"{fname}: no bond type data found (expected C-C, H-H, or O-O)")

    def find_bond_data(d, bond_type, depth=0):
        """Find data associated with a bond type in nested dict."""
        if depth > 3:
            return None
        if isinstance(d, dict):
            if bond_type in <local-path>                return d[bond_type]
            for k, v in d.items():
                result = find_bond_data(v, bond_type, depth + 1)
                if result is not None:
                    return result
        return None

    def has_fluctuation_bounds(data):
        """
        Check if data contains upper/lower bound information.
        Flexible: accepts dict with upper/lower keys, list of dicts, list of lists, etc.
        """
        if isinstance(data, dict):
            keys_lower = set(k.lower() for k in data.keys())
            has_upper = any('upper' in k for k in keys_lower)
            has_lower = any('lower' in k for k in keys_lower)
            if has_upper and has_lower:
                return True
            # Check for bound-related keys
            bound_keywords = ['bound', 'fluct', 'max', 'min', 'high', 'low']
            has_bounds = any(any(kw in k for kw in bound_keywords) for k in keys_lower)
            if has_bounds:
                return True
            # Check if any values are lists (arrays of data)
            list_values = [v for v in data.values() if isinstance(v, list) and len(v) > 0]
            if len(list_values) >= 2:
                return True  # Has multiple arrays, likely bounds
        elif isinstance(data, list):
            if len(data) == 0:
                return False
            if isinstance(data[0], dict):
                keys = set(data[0].keys())
                keys_lower = set(k.lower() for k in keys)
                has_upper = any('upper' in k for k in keys_lower)
                has_lower = any('lower' in k for k in keys_lower)
                if has_upper and has_lower:
                    return True
                bound_keywords = ['bound', 'fluct', 'max', 'min', 'high', 'low']
                has_bounds = any(any(kw in k for kw in bound_keywords) for k in keys_lower)
                if has_bounds:
                    return True
            if isinstance(data[0], list) and len(data[0]) >= 3:
                return True
        return False

    def has_numeric_data(data, min_points=5):
        """
        Check if data contains numeric arrays with at least min_points values.
        Very flexible - accepts dict with list values, list of numbers, list of dicts, etc.
        """
        if isinstance(data, dict):
            for k, v in data.items():
                if isinstance(v, list) and len(v) >= min_points:
                    # Check that at least some values are numeric
                    numeric_count = sum(1 for x in v[:min_points] if isinstance(x, (int, float)))
                    if numeric_count >= min_points:
                        return True
        elif isinstance(data, list):
            if len(data) >= min_points:
                numeric_count = sum(1 for x in data[:min_points] if isinstance(x, (int, float)))
                if numeric_count >= min_points:
                    return True
                # List of dicts
                if isinstance(data[0], dict):
                    return True
                # List of lists
                if isinstance(data[0], list):
                    return True
        return False

    # Step 5: Validate energy JSON has fluctuation bounds
    energy_fname = "pred_fluctuation_energy.json"
    pred_energy = pred_data[energy_fname]

    found_any_bounds = False
    for bond_type in expected_bond_types:
        bond_data = find_bond_data(pred_energy, bond_type)
        if bond_data is not None:
            if has_fluctuation_bounds(bond_data):
                found_any_bounds = True
                break

    # Also check top-level structure for bounds
    if not found_any_bounds:
        all_keys = set()
        def collect_all_keys(d, depth=0):
            if depth > 4 or not isinstance(d, dict):
                return
            for k, v in d.items():
                all_keys.add(k.lower() if isinstance(k, str) else str(k))
                collect_all_keys(v, depth + 1)
        collect_all_keys(pred_energy)
        has_upper = any('upper' in k for k in all_keys)
        has_lower = any('lower' in k for k in all_keys)
        found_any_bounds = has_upper and has_lower

    if not found_any_bounds:
        return (False, f"{energy_fname}: no fluctuation bounds (upper/lower) found in data")

    # Step 6: Validate bond order JSON has data
    # FLEXIBLE: accepts any structure that contains numeric data for bond types
    bo_fname = "pred_fluctuation_bo.json"
    pred_bo = pred_data[bo_fname]

    found_bo_data = False
    for bond_type in expected_bond_types:
        bond_data = find_bond_data(pred_bo, bond_type)
        if bond_data is not None:
            # Accept any of these structures:
            # 1. Dict with list values (e.g., {'upper': [...], 'lower': [...], 'distances': [...]})
            # 2. List of numbers
            # 3. List of dicts
            # 4. List of lists
            if has_numeric_data(bond_data, min_points=3):
                found_bo_data = True
                break
            # Also accept if it has fluctuation bounds (upper/lower)
            if has_fluctuation_bounds(bond_data):
                found_bo_data = True
                break

    if not found_bo_data:
        # Last resort: check if the file has any meaningful numeric data
        all_lists = []
        def collect_lists(d, depth=0):
            if depth > 4:
                return
            if isinstance(d, list) and len(d) >= 3:
                all_lists.append(d)
            elif isinstance(d, dict):
                for v in d.values():
                    collect_lists(v, depth + 1)
        collect_lists(pred_bo)
        if len(all_lists) >= 2:
            found_bo_data = True

    if not found_bo_data:
        return (False, f"{bo_fname}: no valid bond order data found")

