            if isinstance(epochs_list, list) and epochs_list:
                result['has_data'] = True
                for ep in epochs_list:
                    if isinstance(ep, dict):
                        start = ep.get('start_time') or ep.get('start')
                        end = ep.get('end_time') or ep.get('end')
                        label = ep.get('label') or ep.get('tags') or ep.get('tag')
                        if start is not None and end is not None:
                            result['epochs'].append({
                                'label': label,
                                'start': float(start),
                                'end': float(end)
                            })

            # Time support
            ts = entry.get('time_support')
            if isinstance(ts, dict) and ts:
                result['has_data'] = True
                result['time_support'] = ts
            elif ts is not None:
                result['has_data'] = True
                result['time_support'] = ts

        # Process top-level or per-file entries
        # Check if top-level has direct data fields
        if any(k in pred_data for k in ['position_loaded', 'position_data', 'epochs', 'time_support']):
            process_entry(pred_data)
        else:
            # Per-file structure
            for key, value in pred_data.items():
                if isinstance(value, dict):
                    process_entry(value)

        return result

    extracted = extract_all_data(pred)

    # Check if any NWB files were found and processed
    nwb_dir = 'benchmark/datasets/pynapple/tests/nwbfilestest'
    nwb_files = []
    if os.path.exists(nwb_dir):
        for root, dirs, files in os.walk(nwb_dir):
            for f in files:
                if f.endswith('.nwb'):
                    nwb_files.append(os.path.join(root, f))

    if not nwb_files:
        # No NWB files to process - check if pred has reasonable empty structure
        if isinstance(pred, dict):
            return (True, "No NWB files found in dataset directory. Output file created with empty results.")
        return (False, "No NWB files found and output is not a valid dict")

    # Check that pred has entries for NWB files
    pred_has_file_entries = False
    for nwb_file in nwb_files:
        if nwb_file in pred:
            pred_has_file_entries = True
            break
        # Check relative path variants
        rel_path = os.path.relpath(nwb_file)
        if rel_path in pred:
            pred_has_file_entries = True
            break

    if pred_has_file_entries or any(k in pred for k in ['position_loaded', 'position_data', 'epochs', 'time_support']):
        components_passed += 1  # File structure component
    else:
        failures.append("No NWB file entries found in output (expected file paths or data fields as keys)")

    # Check if data was successfully extracted
    if extracted['has_data'] or len(extracted['errors']) < len(nwb_files):
        components_passed += 1  # Data loading component

    # Check position data
    if extracted['position_columns']:
        components_passed += 1  # Position data component
        # Verify x, y present
        for col in ['x', 'y']:
            if col not in extracted['position_columns']:
                failures.append(f"Expected position column '{col}' not found")
    else:
        # Check if there were errors that prevented loading
        if extracted['errors']:
            failures.append(f"Position data not extracted. Errors: {extracted['errors'][:2]}")
        else:
            failures.append("No position data (x, y, z) found in output")

    # Check compass/rotation data
    if extracted['compass_columns']:
        components_passed += 1  # Compass data component
    else:
        failures.append("No compass direction data (rx, ry, rz) found in output")

    # Check epochs
    if extracted['epochs']:
        components_passed += 1  # Epochs component
        # Verify epochs have valid structure
        valid_epochs = 0
        for ep in extracted['epochs']:
            if ep['start'] < ep['end']:
                valid_epochs += 1
            else:
                failures.append(f"Invalid epoch: start={ep['start']} >= end={ep['end']}")
        if valid_epochs > 0:
            pass  # Good
        else:
            failures.append("No valid epochs with start < end found")
    else:
        failures.append("No epoch data found in output")

    # Check time support
    if extracted['time_support'] is not None:
        components_passed += 1  # Time support component
    else:
        failures.append("No time support data found in output")

    # Compare with gold if available
    gold_comparison_issues = []
    if gold is not None:
        gold_extracted = extract_all_data(gold)

        # Compare epoch counts (allow some tolerance)
        if gold_extracted['epochs'] and extracted['epochs']:
            if len(extracted['epochs']) != len(gold_extracted['epochs']):
                gold_comparison_issues.append(
                    f"Epoch count: pred={len(extracted['epochs'])}, gold={len(gold_extracted['epochs'])}"
                )

        # Compare position columns
        if gold_extracted['position_columns'] and extracted['position_columns']:
            missing = gold_extracted['position_columns'] - extracted['position_columns']
            if missing:
