        # Compare compass columns
        if gold_extracted['compass_columns'] and extracted['compass_columns']:
            missing = gold_extracted['compass_columns'] - extracted['compass_columns']
            if missing:
                gold_comparison_issues.append(f"Missing compass columns vs gold: {missing}")

    # Calculate completeness
    completeness = (components_passed / total_components) * 100

    # Build result message
    all_issues = failures + ([f"Gold comparison: {'; '.join(gold_comparison_issues)}"] if gold_comparison_issues else [])

    if completeness >= 60 and not failures:
        return (
            True,
            f"All checks passed. Completeness: {completeness:.1f}% ({components_passed}/{total_components} components). "
            + (f"Gold comparison notes: {'; '.join(gold_comparison_issues)}" if gold_comparison_issues else ""),
        )
    elif completeness >= 60:
        return (
            True,
            f"Mostly passed. Completeness: {completeness:.1f}% ({components_passed}/{total_components} components). "
            f"Minor issues: {'; '.join(failures)}",
        )
    else:
        return (
            False,
            f"Completeness score {completeness:.1f}% < 60% threshold. "
            f"Passed {components_passed}/{total_components} components. Issues: {'; '.join(all_issues) if all_issues else 'none'}",
